// ELEMENTOS PRINCIPALES:

// 1. OBJETOS (participants): cajas en la parte superior
//    [GameManager]  [Player]  [UI]  [EnemyAI]

// 2. LIFELINES (líneas de vida): líneas verticales punteadas
//    que bajan de cada objeto, representando su existencia en el tiempo

// 3. MENSAJES SÍNCRONOS: flecha sólida →
//    El emisor espera la respuesta antes de continuar
//    GameManager → Player : Inicializar()

// 4. MENSAJES DE RESPUESTA: flecha punteada - - →
//    Retorno de un mensaje síncrono
//    Player - - → GameManager : return vida

// 5. ACTIVACIÓN (activation bar): rectángulo delgado sobre la lifeline
//    Indica que el objeto está procesando (ejecutando un método)

// 6. TIEMPO: fluye de arriba hacia abajo
//    El primer mensaje está arriba, el último abajo

// SEQUENCE DIAGRAM: El jugador recibe daño de un enemigo

[EnemyAI]          [Player]          [UIManager]
    |                  |                   |
    |──Atacar(10)──→   |                   |
    |                  |──ActualizarVida──→ |
    |                  |                   |
    |                  | ←──UpdateUI()──── |
    |                  |                   |
// Lectura:
// 1. EnemyAI envía Atacar(10) a Player  (mensaje síncrono →)
// 2. Player envía ActualizarVida a UIManager
// 3. UIManager confirma con UpdateUI() a Player
// El tiempo fluye de arriba hacia abajo: primero ocurre Atacar,
// luego ActualizarVida, luego UpdateUI.

// SEQUENCE DIAGRAM:
// [GameManager] → [SceneLoader] : CargarEscena("Nivel2")
// [SceneLoader] → [AudioManager] : DetenerMusica()
// [SceneLoader] - - → [GameManager] : return OK

// CÓDIGO C# EQUIVALENTE:
public class GameManager : MonoBehaviour
{
    public void IrSiguienteNivel()
    {
        // Mensaje 1: GameManager → SceneLoader
        sceneLoader.CargarEscena("Nivel2");
    }
}

public class SceneLoader : MonoBehaviour
{
    public void CargarEscena(string nombre)
    {
        // Mensaje 2: SceneLoader → AudioManager
        audioManager.DetenerMusica();
        // ... cargar escena
        // Mensaje 3: retorno implícito al GameManager
    }
}

